package exercise

func LongestOnesAfterDeletion(nums []int) int {
	best, zeros, left := 0, 0, 0
	for right, x := range nums {
		if x == 0 {
			zeros++
		}
		for zeros > 1 {
			if nums[left] == 0 {
				zeros--
			}
			left++
		}
		if right-left > best {
			best = right - left
		}
	}
	return best
}

