func TestLongestUniqueSubstring(t *testing.T) {
	cases := []struct {
		name string
		s    string
		want int
	}{
		{"repeats every three", "abcabcbb", 3},
		{"one letter over and over", "bbbbb", 1},
		{"answer is not a prefix", "pwwkew", 3},
		{"empty string", "", 0},
		{"single character", "a", 1},
		{"spaces count as characters", "a b c", 3},
		{"no repeats at all", "abcdef", 6},
		{"two nested pairs", "abba", 2},
		{"repeat in the middle", "dvdf", 3},
		{"digits and symbols", "12!3!45", 4},
		{"counts characters, not bytes", "héllo wörld", 7},
		{"non-latin text", "日本語日本", 3},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := LongestUniqueSubstring(c.s); got != c.want {
				t.Errorf("LongestUniqueSubstring(%q) = %d, want %d", c.s, got, c.want)
			}
		})
	}
}

func TestLongestUniqueSubstringIsLinear(t *testing.T) {
	const distinct = 100000
	var b strings.Builder
	for i := 0; i < distinct; i++ {
		b.WriteRune(rune(0x10000 + i))
	}
	s := strings.Repeat(b.String(), 2)

	const budget = 2 * time.Second
	start := time.Now()
	got := LongestUniqueSubstring(s)
	elapsed := time.Since(start)

	if got != distinct {
		t.Fatalf("got %d, want %d", got, distinct)
	}
	if elapsed > budget {
		t.Fatalf("took %v on %d characters, over the %v budget", elapsed, 2*distinct, budget)
	}
}

