package exercise

func LongestUniqueSubstring(s string) int {
	lastSeen := make(map[rune]int)
	best, left := 0, 0
	for right, r := range []rune(s) {
		if i, ok := lastSeen[r]; ok && i >= left {
			left = i + 1
		}
		lastSeen[r] = right
		if right-left+1 > best {
			best = right - left + 1
		}
	}
	return best
}
